const size_t bb_static_context_count=sizeof(bb_static_contexts)/sizeof(bb_static_contexts[0]);
const BBStaticContext *bb_static_context_find(uint8_t bank,uint16_t pc){size_t lo=0,hi=bb_static_context_count;while(lo<hi){size_t m=lo+(hi-lo)/2;const BBStaticContext*x=&bb_static_contexts[m];if(x->bank<bank||(x->bank==bank&&x->pc<pc))lo=m+1;else hi=m;}if(lo<bb_static_context_count&&bb_static_contexts[lo].bank==bank&&bb_static_contexts[lo].pc==pc)return &bb_static_contexts[lo];return 0;}
